class LibraryManagementSystemSystem_AutoGenerated {
  /*The scheduler counts down the suspension days for users who have overdue books, suspending their borrowing privileges once the suspension period is over.*/
  countDownSuspensionDay(): void {
    /*Definition Start*/
    let obs: User[] = l({
      logic: () =>
        getRepository(User).filter(
          (o: any) =>
            l({
              logic: () =>
                o.LoanedBook.some(
                  (_l: any) =>
                    l({
                      logic: () => _l.OverDue3Days,
                      description: "l.OverDue3Days",
                    })
                      .or({
                        logic: () => _l.OverDue10Days,
                        description: "l.OverDue10Days",
                      })
                      .or({
                        logic: () => _l.OverDue17Days,
                        description: "l.OverDue17Days",
                      })
                      .or({
                        logic: () => _l.OverDue31Days,
                        description: "l.OverDue31Days",
                      })
                      .build().pass,
                ),
              description:
                "o.LoanedBook->exists(l|l.OverDue3Daysorl.OverDue10Daysorl.OverDue17Daysorl.OverDue31Days)",
            }).build().pass,
        ),
      description:
        "User.allInstance()->select(o|o.LoanedBook->exists(l|l.OverDue3Daysorl.OverDue10Daysorl.OverDue17Daysorl.OverDue31Days))",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () =>
          obs.forEach(
            (o: any) =>
              l({
                logic: () => o.SuspensionDays > 0,
                description: "o.SuspensionDays>0",
              })
                .and({
                  logic: () => o.BorrowStatus === BorrowStatus.NORMAL,
                  description: "o.BorrowStatus=BorrowStatus::NORMAL",
                })
                .and({
                  logic: () =>
                    o.LoanedBook.some(
                      (_l: any) =>
                        l({
                          logic: () => _l.OverDue3Days,
                          description: "l.OverDue3Days",
                        })
                          .or({
                            logic: () => _l.OverDue10Days,
                            description: "l.OverDue10Days",
                          })
                          .or({
                            logic: () => _l.OverDue17Days,
                            description: "l.OverDue17Days",
                          })
                          .or({
                            logic: () => _l.OverDue31Days,
                            description: "l.OverDue31Days",
                          })
                          .build().pass,
                    ),
                  description:
                    "o.LoanedBook->exists(l|l.OverDue3Daysorl.OverDue10Daysorl.OverDue17Daysorl.OverDue31Days)",
                })
                .build().pass,
          ),
        description:
          "obs->forAll(o|o.SuspensionDays>0ando.BorrowStatus=BorrowStatus::NORMALando.LoanedBook->exists(l|l.OverDue3Daysorl.OverDue10Daysorl.OverDue17Daysorl.OverDue31Days))",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () =>
        obs.forEach(
          (o: any) =>
            l({
              execute: () => (o.SuspensionDays = o.SuspensionDays - 1),
              description: "o.SuspensionDays=o.SuspensionDays-1",
            })
              .and({
                execute: () => (o.BorrowStatus = BorrowStatus.SUSPEND),
                description: "o.BorrowStatus=BorrowStatus::SUSPEND",
              })
              .build().value,
        ),
      description:
        "obs->forAll(o|o.SuspensionDays=o.SuspensionDays-1ando.BorrowStatus=BorrowStatus::SUSPEND)",
    }).build().value;
    /*Postcondition End*/
  }
}
export { LibraryManagementSystemSystem_AutoGenerated };

